sets.css:
@media (prefers-reduced-motion: no-preference) {
  body.cas-flourish-subtle .family-card,
  body.cas-flourish-subtle .resource-card,
  body.cas-flourish-subtle figure {
    transition: transform 0.18s ease, box-shadow 0.18s ease;
  }
  body.cas-flourish-subtle .family-card:hover,
  body.cas-flourish-subtle .resource-card:hover,
  body.cas-flourish-subtle figure:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 20px rgba(0,0,0,0.06);
  }
  body.cas-flourish-subtle main {
    animation: cas-fade-in 0.5s ease-out;
  }
  body.cas-flourish-subtle a:not(.btn):not(.brand):hover {
    text-decoration-color: var(--color-primary);
    text-decoration-thickness: 2px;
    text-underline-offset: 3px;
  }
}
@keyframes cas-fade-in {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

@media (prefers-reduced-motion: no-preference) {
  /* The drop-cap rule itself lives in global style.css under
     `.cas-drop-cap::first-letter` so any flourish set + any widget that
     opts in via `drop_cap: true` (currently the about-page hero) gets
     the editorial first-letter. The literary flourish layer adds an
     italic-display tilt to make the cap feel more book-like. */
  body.cas-flourish-literary .cas-drop-cap::first-letter {
    font-style: italic;
    font-weight: 700;
  }
  body.cas-flourish-literary a:not(.btn):not(.brand) {
    background-image: linear-gradient(to right, var(--color-primary), var(--color-primary));
    background-position: 0 100%;
    background-repeat: no-repeat;
    background-size: 0% 1px;
    transition: background-size 0.28s ease;
    text-decoration: none;
    padding-bottom: 1px;
  }
  body.cas-flourish-literary a:not(.btn):not(.brand):hover {
    background-size: 100% 1px;
  }
}

@media (prefers-reduced-motion: no-preference) {
  body.cas-flourish-expressive section:first-of-type h1 {
    background: linear-gradient(120deg, var(--color-primary), var(--color-primary-dark, var(--color-primary)));
    -webkit-background-clip: text;
    background-clip: text;
    -webkit-text-fill-color: transparent;
    color: transparent;
  }
  body.cas-flourish-expressive .btn,
  body.cas-flourish-expressive a.btn,
  body.cas-flourish-expressive button[type="submit"] {
    transition: box-shadow 0.22s ease, transform 0.18s ease;
  }
  body.cas-flourish-expressive .btn:hover,
  body.cas-flourish-expressive a.btn:hover,
  body.cas-flourish-expressive button[type="submit"]:hover {
    box-shadow: 0 0 0 4px color-mix(in oklab, var(--color-primary) 22%, transparent);
    transform: translateY(-1px);
  }
  body.cas-flourish-expressive section:first-of-type {
    position: relative;
    overflow: hidden;
  }
  body.cas-flourish-expressive section:first-of-type::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse at 30% 30%, color-mix(in oklab, var(--color-primary) 8%, transparent) 0%, transparent 60%);
    pointer-events: none;
    z-index: 0;
  }
  body.cas-flourish-expressive section:first-of-type > * {
    position: relative;
    z-index: 1;
  }
}
